mapper.sql:
FROM bank_transaction bt INNER JOIN linked_bank_account account ON account.linked_account_id = bt.linked_account_id WHERE account.user_id = #{userId} AND account.connection_status = 'AVAILABLE' AND bt.processing_status = 'NEEDS_CHECK' AND bt.transaction_type = 'DEPOSIT' AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE'
)
AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = 'SETTLEMENT'
) AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = 'LOAN'
)
AND NOT ( EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = 'SETTLEMENT'
) AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = 'LOAN'
) )
AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = #{condition.targetType}
)
AND EXISTS ( SELECT 1 FROM bank_transaction_match_candidate available_candidate LEFT JOIN payment_obligation obligation ON available_candidate.target_type = 'SETTLEMENT' AND obligation.payment_obligation_id = available_candidate.target_id LEFT JOIN settlement_participant participant ON participant.participant_id = obligation.participant_id LEFT JOIN repayment_schedule schedule ON available_candidate.target_type = 'LOAN' AND schedule.schedule_id = available_candidate.target_id WHERE available_candidate.bank_transaction_id = bt.bank_transaction_id AND available_candidate.candidate_status = 'AVAILABLE' AND available_candidate.target_type = #{condition.targetType}
AND CASE WHEN available_candidate.target_type = 'SETTLEMENT' THEN participant.settlement_id WHEN available_candidate.target_type = 'LOAN' THEN schedule.contract_id END = #{condition.aggregateId} )
